from pathlib import Path
import re,json,html,base64
root=Path(__file__).resolve().parents[1];template=(root/'tools/guide-base.html').read_text()
evidence=json.loads((root/'VALIDATION.json').read_text())
css=re.search(r'<style>(.*?)</style>',template,re.S).group(1)
colors={'#f6f4f1':'#f4f7fa','#1a1214':'#16324b','#6b5a5f':'#526878','#9c8b8e':'#667d8d','#ece2e4':'#dae5ed','#ddc9cd':'#c1d2df','#7b0431':'#087f8c','#fdf0f5':'#e6f5f5','#8a5a3c':'#087f8c','#f3e7dd':'#e9f6f5','#6d3350':'#46628a','#f3e6ec':'#edf2fa','#d4365a':'#21a8aa','#180f12':'#122c42'}
for a,b in colors.items():css=css.replace(a,b)
clean_template=re.sub(r'<!--.*?-->','',template,flags=re.S)
scripts=clean_template[clean_template.index('<script>'):len(clean_template)]
glossary={'LiteLLM':'The customer gateway that authenticates keys, selects providers and records requests.','OAuth':'An account sign-in token. Claude Code manages the Claude subscription login; LiteLLM stores the personal Copilot connection.','fallback':'Retrying an eligible failed request on the backup selected by the key policy.','virtual key':'A personal LiteLLM access key, separate from either provider login.','429':'A provider rate-limit response. It does not by itself prove that a subscription usage window is exhausted.','PostgreSQL':'The gateway database containing routes, users, keys and encrypted provider connections.','alias':'The model name that a client sends to LiteLLM.'}
scripts=re.sub(r'var GLOSSARY = \{.*?\};','var GLOSSARY = '+json.dumps(glossary)+';',scripts,count=1,flags=re.S)
nav=[('start','Start here'),('admin','Administrator setup'),('developer','Developer onboarding'),('architecture','Architecture & identity'),('models','Models & fallback'),('verify','Verify the deployment'),('troubleshoot','Fix a problem'),('operations','Renewal & offboarding'),('evidence','Validation'),('decisions','Before customer rollout'),('glossary','Glossary')]
commands=[]
def cmd(s,label='Terminal',id=None):
 ident=id or 'cmd-'+str(len(commands));commands.append({'id':ident,'command':s,'context':label})
 return f'<div class="command"><div class="command-head"><span>{html.escape(label)}</span><button class="copy" data-copy="{ident}" aria-label="Copy {html.escape(s,quote=True)}">Copy</button></div><pre class="arch" id="{ident}">{html.escape(s)}</pre></div>'
def section(id,title,content):return f'<section id="{id}"'+(' hidden data-journey="'+id+'"' if id in ("admin","developer") else '')+f'><div class="sec-num">{"ADMINISTRATOR ONLY" if id=="admin" else "DEVELOPER ONLY" if id=="developer" else "SHARED REFERENCE" if id!="start" else "CHOOSE YOUR PATH"}</div><h2>{title}</h2>{content}</section>'
def table(headers,rows):return '<div class="tbl-wrap"><table><thead><tr>'+''.join('<th>'+x+'</th>' for x in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+str(x)+'</td>' for x in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def note(text,kind=''):return '<div class="note '+kind+'"><span class="ic" aria-hidden="true">i</span><div>'+text+'</div></div>'
def figure(name,alt,caption):
 p=root/'diagrams'/name
 src='data:image/png;base64,'+base64.b64encode(p.read_bytes()).decode() if p.exists() else 'diagrams/'+name
 return '<figure><button class="zoom" aria-label="Enlarge '+html.escape(alt,quote=True)+'"><img src="'+src+'" alt="'+html.escape(alt,quote=True)+'"></button><figcaption>'+caption+' · Select image to enlarge</figcaption></figure>'
body='''<header class="hero"><div class="eyebrow">CUSTOMER ENABLEMENT · CLAUDE GATEWAY</div><h1 class="title">A clear path from<br><em>setup to everyday work.</em></h1><p class="lede">Claude Teams first. Personal GitHub Copilot backup. A guided CLI for the administrator and every developer.</p><p class="download-links"><a href="https://github.com/msftse-org/claude-teams-litellm-copilot/releases/latest/download/claude-gateway-cli.zip">Download CLI package</a> · <a href="https://github.com/msftse-org/claude-teams-litellm-copilot">View source code</a></p><div class="role-links" id="role-picker" aria-label="Choose your onboarding role"><button class="role-choice" data-role="admin" aria-pressed="false"><strong>I’m an administrator</strong><span>Prepare the gateway · invite developers</span><b class="selection">Choose administrator →</b></button><button class="role-choice" data-role="developer" aria-pressed="false"><strong>I’m a developer</strong><span>Use my invitation · connect my accounts</span><b class="selection">Choose developer →</b></button><a href="#evidence">Review validation results</a></div><div class="meta-row"><span class="meta-pill"><b>Scope</b> Existing customer LiteLLM</span><span class="meta-pill"><b>Platform tested</b> macOS</span><span class="meta-pill"><b>Updated</b> 10 November 2026</span></div></header>'''
body+=section('start','Start with your role.', '<p class="lead-p">Choose your role above. No role is selected by default. Your setup steps appear only after you choose; architecture, model choices and validation results are shared reference material.</p>'+'''<div class="cards c2"><div class="card ac"><div class="ct">Administrator</div><p>Prepare the gateway once. Issue a separate invitation for each developer and choose their automatic backups.</p></div><div class="card rd"><div class="ct">Developer</div><p>Import your invitation, connect your own accounts, pass the checks, then run Claude Code normally.</p></div></div>'''+note('The wizard uses Python internally. You do not edit Python, YAML, or JSON during the normal onboarding flow. The HTML guide works offline; live onboarding requires network access.')+figure('02-onboarding-handoff.png','Administrator-to-developer onboarding flow','Figure 1. The invitation is the handoff. It contains a personal gateway key, not provider credentials.'))
body+=section('admin','Administrator: prepare, then invite.', '''<p class="lead-p">You need an existing reachable gateway, its administrator key, PostgreSQL, and permission to manage models, credentials and users.</p><details><summary>Gateway prerequisites and compatibility</summary><ul><li>Customer HTTPS origin, for example <code>https://litellm.customer.example</code>. Do not append <code>/v1</code>.</li><li>Database-backed model storage enabled: <code>general_settings.store_model_in_db: true</code>.</li><li>Validated server version: LiteLLM <strong>1.108.0</strong>. Other versions require the same acceptance checks.</li><li>Gateway egress to Anthropic and GitHub Copilot. Developers must reach the gateway and account sign-in pages.</li><li>Administrator key available privately. The wizard keeps it in memory only.</li></ul></details><h3>Admin step 1 · Open the package and check Python</h3><p>Download and extract the package, or clone the repository. Open the folder containing <code>setup</code> in Terminal or iTerm. All commands in this journey run there.</p>'''+cmd('python3 --version')+'''<p class="expected">Expected: Python 3.10 or newer. If unavailable, ask IT to install an approved Python distribution before continuing.</p><h3>Admin step 2 · Prepare the customer gateway</h3>'''+cmd('./setup admin')+'''<ol><li>Choose <strong>Prepare customer gateway</strong>.</li><li>Enter the gateway origin and hidden administrator key.</li><li>Leave optional Copilot Opus disabled unless the customer has verified access.</li><li>Review the planned credential and model routes, then approve the change.</li></ol><p class="expected">Expected: “Gateway ready. Next: Invite a developer.” Repeating preparation preserves matching routes. Conflicting routes stop the wizard for review.</p><h3>Admin step 3 · Create a private invitation file</h3><ol><li>Choose <strong>Invite a new developer</strong> from the same menu.</li><li>Enter the developer’s work email (gateway record only) and exact GitHub username.</li><li>Choose the recommended policy, or select a backup for each primary family.</li><li>Choose a private invitation file location. Review and confirm.</li></ol><p class="expected">Expected: “Invitation ready” and a file with owner-only permissions. Each key expires after 90 days.</p><h3>Admin step 4 · Deliver the private invitation</h3><p><strong>No email is sent by the wizard.</strong> Share the package and the developer’s <code>.invite.json</code> through an organization-approved private channel, such as a recipient-restricted file share, password-manager share, or approved direct message. Include the support contact. Tell them which Claude organization and GitHub account to select. Each developer needs their own eligible Claude seat and Copilot access.</p>'''+note('Repeat only the invitation step for the next developer. Never distribute the master key or share one developer’s invitation with the team.','amber')+'''<details><summary>Why do we ask for a work email if no email is sent?</summary><p>It labels the user in LiteLLM and is part of the stable identifier used by this installer for that gateway. Repeat enrollment with the same address reuses the same user; changing it creates a different identity. The key is linked to that user for ownership and usage records.</p><p>The address is not verified and does not sign the developer into Claude or GitHub. The GitHub username is checked against the connected Copilot account. Claude Code handles the subscription login separately.</p><p>The installer explicitly sets <code>send_invite_email: false</code> for both user and key creation. No SMTP service is needed for this file-based flow.</p></details><details><summary>Can LiteLLM send invitations by email instead?</summary><p>Yes. LiteLLM has native email integrations using SMTP, Resend or SendGrid. The customer must configure its email integration and enable the desired notification or invite workflow. That native email does not automatically attach this package’s custom <code>.invite.json</code> file.</p><p>For this release, use the tested private-file handoff. Email-based delivery would be a separate integration and acceptance test; the wizard does not configure it. See <a href="https://docs.litellm.ai/docs/proxy/email">LiteLLM email notifications</a>.</p></details><h3>Ready-to-send handoff</h3><p>Use <strong>HANDOFF-TEMPLATE.txt</strong> from the package. Send it with the approved package link and a private link or attachment for this developer’s invitation. Do not paste the key into the message.</p>''')
body+=section('developer','Developer: join once, then use Claude.', '''<p class="lead-p">Keep your private invitation ready. You need Claude Code, Python 3.10+, a Claude subscription account and the GitHub account named in the invitation.</p><h3>Developer step 1 · Open the package and check your tools</h3><p>Get the package and your private invitation from your administrator. Open the folder containing <code>setup</code> in Terminal or iTerm. You do not need the gateway administrator key or to run administrator setup.</p>'''+cmd('python3 --version')+cmd('claude --version')+'''<p class="expected">The test environment used Claude Code 2.1.317. If <code>claude</code> is missing, use your organization’s approved installation process.</p><h3>Developer step 2 · Join your gateway</h3>'''+cmd('./setup developer')+'''<ol><li>Choose <strong>Join with my invitation</strong>.</li><li>Paste the invitation path or drag the file into Terminal.</li><li>Review the gateway and expected GitHub identity. Approve the setup checks.</li><li>If prompted, complete the GitHub device flow with that account. Complete Claude subscription sign-in when requested.</li><li>Wait for model checks, the settings backup, and the Claude Code test.</li></ol><p class="expected">Expected: “READY — restart open Claude sessions, then run: claude”. An already connected account is verified instead of asking you to sign in again.</p>'''+note('Your existing permissions and unrelated settings are retained. Gateway authentication, model defaults and conflicting provider settings are updated. A private backup is saved before changes.')+'''<h3>Developer step 3 · Restart and work normally</h3>'''+cmd('claude')+'''<p>Inside Claude Code, type a small prompt, such as <strong>Reply with exactly MY_GATEWAY_TEST</strong>. The administrator should locate that request in LiteLLM Logs. No special launcher is needed.</p><h3>Developer step 4 · Check your connection and models</h3>'''+cmd('./setup doctor')+cmd('./setup models')+'''<p class="expected">Doctor verifies the connected identity, Copilot inference and a Claude Code reply. Models displays your key’s live policy; before joining it explicitly shows starter defaults.</p><details><summary>What changes in my settings?</summary><p>The wizard writes <code>~/.claude/settings.json</code>: the customer gateway URL, a personal <code>x-litellm-api-key</code> header, three primary model defaults, and Sonnet as the initial model. It removes a conflicting <code>apiKeyHelper</code> so Claude Code can use its subscription login. Shell, project and managed settings can still override user settings; check them if routing differs.</p><p>Private backups: <code>~/.claude/backups/gateway-…/settings.json</code>. Onboarding state and a diagnostic report also live under <code>~/.claude</code>.</p></details>''')
body+=section('architecture','Two sign-ins. One routing policy.',figure('01-request-architecture.png','Claude Code to customer LiteLLM, Anthropic primary and personal Copilot backup','Figure 2. Provider identities stay personal; the gateway applies access and fallback policy.')+table(['Component','Responsibility','Configuration owner'],[['Claude Code','Maintains the Claude subscription sign-in and conversation. Sends the personal gateway key separately.','Developer'],['LiteLLM','Authenticates the virtual key; tries the primary and the configured backup.','Administrator'],['Anthropic','Serves requests using the developer’s eligible Claude subscription.','Developer’s Claude organization'],['GitHub Copilot','Serves backup or direct Copilot requests using the key owner’s connection.','Developer’s GitHub organization'],['PostgreSQL','Stores model routes, users, keys and encrypted Copilot connections.','Customer gateway operator']])+'''<h3>Where an administrator can inspect it</h3><ul><li><strong>Models + Endpoints:</strong> the Anthropic wildcard and explicit Copilot aliases.</li><li><strong>LLM Credentials:</strong> <code>github-copilot-user</code> with per-user OAuth.</li><li><strong>Virtual Keys → Router Settings:</strong> each developer’s fallback mappings and retry settings.</li><li><strong>Logs:</strong> the actual provider/model, request status and fallback attempts.</li></ul><p>This package adds no custom request adapter, shared provider token or modified LiteLLM image. Hosting, TLS, logging retention and availability remain part of the existing customer deployment.</p>''')
body+=section('models','Choose the primary. Let the gateway handle failover.',figure('03-fallback-behavior.png','Primary failure and fallback response flow','Figure 3. A configured provider failure can trigger the backup; later requests try the primary again.')+table(['Claude Code primary','Default Copilot backup'],[['Sonnet 5.5 · initial selection','Sonnet 5.5'],['Opus 5.5','Sonnet 5.5'],['Haiku 5.5','Haiku 5.5'],['Sonnet 5','Sonnet 5'],['Haiku 4.5','Haiku 4.5']])+'''<h3>Switch during a conversation</h3><p>Inside Claude Code, use <code>/model</code> and choose Sonnet, Opus or Haiku. The primary model name stays the requested model; inspect the gateway Logs to know which provider served a particular request.</p><h3>Explicit Copilot choices</h3>'''+table(['Direct alias in Claude Code','Underlying Copilot model'],[['<code>/model claude-copilot-sonnet</code>','Sonnet 5.5'],['<code>/model claude-copilot-haiku</code>','Haiku 5.5'],['<code>/model claude-copilot-sonnet-5</code>','Sonnet 5'],['<code>/model claude-copilot-haiku-4-5</code>','Haiku 4.5']])+note('Optional Copilot Opus 5.5 requires verified entitlement and admin enablement. It was not available in the tested account. The backup catalog is explicit. The Anthropic wildcard may expose additional primary models in the picker; those do not automatically acquire a tested fallback. Use the mappings listed here for the validated path.','amber')+'''<details><summary>Exact failure policy and limits</summary><ul><li>Key-level <code>num_retries: 0</code>; one configured backup for each mapped primary.</li><li>General provider failures, including 429, can trigger fallback. This is not a quota-only condition.</li><li>Direct Copilot aliases have no further fallback. If both primary and backup fail, the request fails.</li><li>Deployment cooldown is disabled for these shared routes so one seat’s failure does not cool down every user’s route. A later request tries the primary again.</li><li>Context-window fallbacks are empty on generated keys. Existing global content-policy settings still need customer review.</li><li>A partial stream cannot be assumed to replay seamlessly. Model output quality, latency and native tool capabilities can differ.</li></ul></details><details><summary>Web search and other tools</summary><p>The tested Read-tool flow works through the primary and Copilot. That does not establish parity for every tool. Anthropic’s native WebSearch previously failed on Copilot. The optional GitHub MCP search setup is separate and is not silently enabled by this wizard. Agree on and test the customer’s search path before rollout.</p></details>''')
body+=section('verify','Verify before onboarding the whole team.', '''<p class="lead-p">Use one pilot developer first. A successful reply proves connectivity; a successful fallback needs separate routing evidence.</p>'''+table(['Check','What to do','Pass condition'],[['Admin preparation','Run preparation twice.','Matching routes remain; no duplicate models.'],['Identity','Join with the intended invitation and accounts.','Expected GitHub username verified; subscription login active.'],['Provider access','Complete Join and run doctor.','All offered Copilot probes pass; Claude Code returns a reply.'],['Normal terminal','Restart Claude and send MY_GATEWAY_TEST.','Request appears on the customer gateway.'],['Model switching','Select each supported primary and direct alias.','Expected model responds.'],['Real fallback','When the provider returns a real eligible error, inspect the resulting request.','Copilot model + successful status + attempted_fallbacks greater than zero.'],['Tools','Run a harmless Read operation on both routes.','Tool call and final reply succeed.'],['Undo','Use Restore previous settings in an isolated pilot profile.','Original settings restored; later edits are protected.']])+note('Do not call a direct Copilot reply or a locally injected error “real subscription failover.” A 429 can mean a short-term rate limit; confirm the subscription usage window separately when that distinction matters.','amber')+'''<h3>Evidence to capture from LiteLLM</h3><p>Record the request ID, requested model group, actual model, status, <code>used_client_oauth_token</code> and <code>attempted_fallbacks</code>. Prompt storage is not required for this routing check. If prompt storage is enabled, apply the customer’s retention policy.</p>''')
body+=section('troubleshoot','Recover with a clear next step.', '''<p>Start with <code>./setup doctor</code>. It avoids printing upstream error bodies that may include sensitive content.</p>'''+table(['Symptom','Likely check','Next action'],[['“This machine has not joined yet”','No onboarding state exists.','Run ./setup developer → Join.'],['Gateway HTTP 401 / 403','Expired key, wrong role or blocked route.','Administrator inspects the personal key and its allowed routes.'],['Wrong GitHub account','Invitation and connected account differ.','Use the intended account; settings are not changed before this check passes.'],['429 reaches Claude Code','Primary and backup may both have failed.','Inspect both provider errors and the key’s policy in gateway Logs.'],['Native WebSearch fails on Copilot','Provider capability mismatch.','Use a separately approved and tested search tool; do not claim model parity.'],['“Conflicting route”','An existing route differs from the package.','Administrator reviews it before changing shared routing.'],['Model probe fails','Model not enabled or provider access unavailable.','Resolve entitlement before onboarding; do not ignore failed probes.'],['Restore refuses','Settings changed after onboarding.','Merge the private backup manually; the wizard protects newer edits.']]))
body+=section('operations','Add people without rebuilding the gateway.', '''<div class="cards c2"><div class="card ac"><div class="ct">New developer</div><p>Admin → Invite a new developer. Deliver a distinct invitation. Developer → Join. No gateway redeployment.</p></div><div class="card rd"><div class="ct">Renew or change policy</div><p>Create a new invitation filename and issue a new key. Revoke the previous key as appropriate, then have the developer join again.</p></div><div class="card wr"><div class="ct">Offboard</div><p>Block or delete the developer’s LiteLLM key. Review their provider access separately. Removing local settings does not revoke access.</p></div><div class="card cp"><div class="ct">Restore local settings</div><p>Developer → Restore previous settings. Restore is refused if newer settings edits would be overwritten.</p></div></div><p>The package does not create organization-wide SSO, fleet enrollment, budgets or user rate limits. Preserve existing customer policies and assign an operator to own key renewal and support.</p>''')
body+=section('evidence','Validation and deployment checks.', '<p class="lead-p">Use the repeatable checks below to verify your deployment. This guide contains aggregate results, without provider request IDs, account records or private execution logs.</p>'+table(['Area','Result','Verification'],[['Automated checks',str(evidence['automated_tests'])+' passed','Run the offline test suite.'],['Administrator onboarding','Passed','Prepare routes, create a private invitation and repeat without duplicate models.'],['Developer onboarding','Passed','Validate the invitation, connect accounts and check settings.'],['Primary and direct models','3 primary + 4 Copilot','Verify the models available to your account.'],['Real fallback','3 primary families','A genuine primary limit produced successful Copilot responses.'],['Tool use','Read roundtrips passed','Check the tools your team requires on both providers.'],['Private handoff','No automatic email','Deliver each personal invitation separately.']])+note('See VALIDATION.json for the compatibility summary and docs/VALIDATION.md for exact checks and expected results. Provider capabilities and account entitlements can differ.')+'<details><summary>Deployment-specific checks</summary><p>Complete first-time browser consent and confirm your network, managed policies and model entitlements. Native WebSearch, optional Copilot Opus, all context lengths, production scale and partial-stream failover are outside the verified coverage.</p></details>')
body+=section('decisions','Prepare your organization for onboarding.', '''<p class="lead-p">Confirm the following deployment details so your administrators and developers can follow the same onboarding process.</p><div class="qbox"><div class="qh"><span class="qn">01</span> Deployment ownership</div><p class="ask">Confirm the gateway URL, version, TLS, operator, log retention and support contact.</p></div><div class="qbox"><div class="qh"><span class="qn">02</span> Accounts and available models</div><p class="ask">Confirm each user’s eligible Claude seat, Copilot entitlement, organization permissions and permitted model list.</p></div><div class="qbox"><div class="qh"><span class="qn">03</span> Developer capabilities</div><p class="ask">Agree on web search, MCP tools, context limits and whether a fallback from Opus to Sonnet is acceptable.</p></div><div class="qbox"><div class="qh"><span class="qn">04</span> Deployment verification</div><p class="ask">Use the included real-quota fallback evidence as a reference. Verify identity, model access and required tools on your gateway before onboarding the rest of your team.</p></div>''')
body+=section('glossary','Terms and verified references.',table(['Term','Meaning'],list(glossary.items()))+'''<div class="refbar"><span class="lbl">Official documentation</span><a class="ref" href="https://docs.litellm.ai/docs/tutorials/claude_code_max_subscription">Claude subscriptions</a><a class="ref" href="https://docs.litellm.ai/docs/providers/github_copilot">GitHub Copilot</a><a class="ref" href="https://docs.litellm.ai/docs/proxy/keys_teams_router_settings">Key routing policies</a><a class="ref" href="https://docs.litellm.ai/docs/proxy/reliability">Provider failover</a></div>''')
extra='''
#image-dialog[hidden]{display:none}#image-dialog{position:fixed;inset:0;z-index:1000;background:#0a1a2de8;display:flex;align-items:center;justify-content:center;padding:20px}.image-panel{width:100%;max-width:1700px;max-height:95vh;overflow:auto;background:white;border-radius:12px;padding:15px}.image-panel img{width:100%;height:auto;display:block}
.role-links{display:flex;flex-wrap:wrap;gap:12px;margin:25px 0}.role-links a,.copy,.mobile-nav select{border:1px solid var(--line-strong);border-radius:10px;padding:11px 16px;background:white;font:600 14px var(--sans);color:var(--ink)}.role-links .primary{background:var(--accent);color:white;border-color:var(--accent)}.expected{color:var(--teal);font-size:14px;border-left:3px solid var(--teal);padding-left:14px}.command{margin:20px 0}.command-head{display:flex;justify-content:space-between;align-items:center;font-size:12px;color:var(--muted);padding:0 3px 6px}.copy{padding:5px 12px;cursor:pointer}.command pre.arch{margin:0;font-size:15px}.zoom{border:0;background:none;padding:0;cursor:zoom-in;width:100%}details{background:var(--panel);border:1px solid var(--line);border-radius:12px;padding:15px 18px;margin:18px 0}summary{cursor:pointer;font-weight:650}details p,details li{font-size:14px}.mobile-nav{display:none}dialog{border:0;border-radius:12px;padding:15px;width:96vw;max-width:1700px;max-height:95vh;overflow:auto}dialog::backdrop{background:#0a1a2ddd}dialog img{width:100%;height:auto}.close-zoom{display:block;margin:0 0 12px auto;padding:8px 14px;border-radius:8px;border:1px solid #cbd6df;background:white;cursor:pointer}.skip{position:fixed;left:10px;top:-70px;z-index:100;background:white;padding:10px}.skip:focus{top:10px}button:focus-visible,a:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #cf8e27;outline-offset:4px}aside{background:var(--panel)}code{color:var(--ink);background:var(--bg);border-color:var(--line)}.note{color:var(--ink);border-color:var(--line)}.note.teal{color:var(--ink);border-color:var(--line)}.refbar{background:var(--panel)}thead th{background:var(--bg)}tbody tr:hover{background:var(--accent-soft)}@media(max-width:980px){.mobile-nav{display:block;position:sticky;top:0;background:var(--panel);padding:12px 18px;z-index:50;border-bottom:1px solid var(--line)}.mobile-nav select{width:100%}section{scroll-margin-top:75px}header.hero{padding-top:40px}}@media print{aside,.mobile-nav,.role-links,.copy,.zoom::after,#progress{display:none}.shell{display:block}main{padding:0}section{break-before:auto}.card,figure,table{break-inside:avoid}details{display:block}h2,h3{break-after:avoid}body{background:white}figure{box-shadow:none}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}
'''
ux='''<script>
document.querySelectorAll('.copy').forEach(b=>b.addEventListener('click',async()=>{const t=document.getElementById(b.dataset.copy).textContent;try{if(navigator.clipboard&&window.isSecureContext){await navigator.clipboard.writeText(t)}else{const a=document.createElement('textarea');a.value=t;a.style.position='fixed';a.style.left='-9999px';document.body.appendChild(a);a.select();const ok=document.execCommand('copy');a.remove();if(!ok)throw Error('copy')}b.textContent='Copied';document.getElementById('status').textContent='Command copied'}catch(e){b.textContent='Select command';document.getElementById('status').textContent='Select and copy the command manually'}setTimeout(()=>b.textContent='Copy',2000)}));
const dlg=document.getElementById('image-dialog');document.querySelectorAll('.zoom').forEach(b=>b.addEventListener('click',()=>{const src=b.querySelector('img');const dest=dlg.querySelector('img');dest.src=src.src;dest.alt=src.alt;dlg.hidden=false;document.querySelector('.shell').inert=true;document.querySelector('.mobile-nav').inert=true;document.body.style.overflow='hidden';dlg.querySelector('button').focus()}));function closeImage(){dlg.hidden=true;document.querySelector('.shell').inert=false;document.querySelector('.mobile-nav').inert=false;document.body.style.overflow=''}dlg.querySelector('button').addEventListener('click',closeImage);dlg.addEventListener('click',e=>{if(e.target===dlg)closeImage()});document.addEventListener('keydown',e=>{if(!dlg.hidden&&e.key==='Escape')closeImage();if(!dlg.hidden&&e.key==='Tab'){e.preventDefault();dlg.querySelector('button').focus()}});document.getElementById('section-select').addEventListener('change',e=>{location.hash=e.target.value});
</script>'''
